class Solution {
    public String defangIPaddr(String address) {
        StringBuilder result = new StringBuilder(address.length() + 6);
        for (int i = 0; i < address.length(); i++) {
            char c = address.charAt(i);
            if (c == '.') {
                result.append("[.]");
            } else {
                result.append(c);
            }
        }
        return result.toString();
    }
}

class Solution {
    public String defangIPaddr(String address) {
        char[] output = new char[address.length() + 6];
        int write = 0;
        for (int i = 0; i < address.length(); i++) {
            char c = address.charAt(i);
            if (c == '.') {
                output[write++] = '[';
                output[write++] = '.';
                output[write++] = ']';
            } else {
                output[write++] = c;
            }
        }
        return new String(output);
    }
}

class Solution {
    public String defangIPaddr(String address) {
        String[] parts = address.split("\\.", -1);
        return String.join("[.]", parts);
    }
}

class Solution {
    public String defangIPaddr(String address) {
        int first = address.indexOf('.');
        int second = address.indexOf('.', first + 1);
        int third = address.indexOf('.', second + 1);
        return address.substring(0, first)
                + "[.]" + address.substring(first + 1, second)
                + "[.]" + address.substring(second + 1, third)
                + "[.]" + address.substring(third + 1);
    }
}
